mod tests {
    use super::*;
    use crate::types::{ElementFlags, ElementRef, Observation};

    fn sample_observation() -> Observation {
        Observation {
            url: "https://example.com".to_string(),
            title: "Example".to_string(),
            viewport: [1280, 800],
            focused: None,
            visible_text: "Hello".to_string(),
            state_hash: "hash".to_string(),
