    use crate::types::{ElementFlags, ElementRef};
    use async_trait::async_trait;
    use std::collections::VecDeque;
    use tokio::sync::Mutex;

    #[derive(Debug)]
    struct FakeBrowser {
        snapshots: Mutex<VecDeque<Observation>>,
        apply_results: Mutex<VecDeque<StepResult>>,
        applied_actions: Mutex<Vec<Action>>,
    }

    impl FakeBrowser {
        fn new(
            snapshots: Vec<Observation>,
            apply_results: Vec<StepResult>,
        ) -> Self {
            Self {
                snapshots: Mutex::new(VecDeque::from(snapshots)),
                apply_results: Mutex::new(VecDeque::from(apply_results)),
                applied_actions: Mutex::new(Vec::new()),
            }
        }

        async fn applied(&self) -> Vec<Action> {
            self.applied_actions.lock().await.clone()
        }
    }

    #[async_trait]
    impl Browser for FakeBrowser {
        async fn snapshot(&self) -> BrowserResult<Observation> {
            let mut guard = self.snapshots.lock().await;
            guard
                .pop_front()
                .ok_or_else(|| BrowserError::new("missing_snapshot", "no snapshot queued"))
        }

        async fn apply(&self, action: &Action) -> BrowserResult<StepResult> {
            self.applied_actions.lock().await.push(action.clone());
            let mut guard = self.apply_results.lock().await;
            guard
                .pop_front()
                .ok_or_else(|| BrowserError::new("missing_result", "no apply result queued"))
        }

        async fn shutdown(&self) -> BrowserResult<()> {
            Ok(())
        }
    }

    #[derive(Debug)]
    struct ScriptedLlm {
        actions: Mutex<VecDeque<Action>>,
    }

    impl ScriptedLlm {
        fn new(actions: Vec<Action>) -> Self {
            Self {
                actions: Mutex::new(VecDeque::from(actions)),
            }
        }
    }

    #[async_trait]
    impl LlmClient for ScriptedLlm {
        async fn propose_action(
            &self,
            _task: &str,
            _plan: Option<&str>,
            _observation: &Observation,
            _history: &[Action],
        ) -> Result<Action, LlmError> {
            let mut guard = self.actions.lock().await;
            guard
                .pop_front()
                .ok_or_else(|| LlmError::new("no_action", "no action queued"))
        }
    }

# Notes

## High-level architecture

A performant Rust “browser + LLM” agent usually ends up as a small state machine with strict interfaces:

* **Browser driver (CDP/WebDriver)**
  * Loads pages, queries DOM/accessibility tree, performs actions.
* **Observer**
  * Produces a compact `Observation` (URL, title, focused element, reduced element list with stable refs).
* **Policy + Router**
  * Chooses which model to call (fast by default, escalations).
  * Tracks failure streaks and “no progress” streaks.
* **Planner / Executor split**
  * Planner (strong model) produces a short plan and constraints.
  * Executor (fast model) emits single-step actions under a schema.
* **Verifier**
  * Deterministic checks first (action references exist, types match, page changed).
  * Optional tiny-model “repair” call when JSON parse or schema validation fails.
* **Memory**
  * Keeps the plan, last N observations, step history, and a progress hash.
* **Telemetry**
  * Tracing spans, counters, and per-step timing. Prometheus if you want dashboards.

## Rust crate choices (common)

* **Tokio** for async runtime.
* **CDP** for performance and richer page introspection.
  * `chromiumoxide` is a common Rust CDP client.
  * WebDriver alternatives: `fantoccini`, `thirtyfour` (often slower and less introspective).
* **Serde** for JSON and action parsing.
* **jsonschema** (or custom validation) for schema validation.
* **tracing`+`tracing-subscriber`** for logs.
* **prometheus`or`opentelemetry`** for metrics.

